code_example:
struct ManagedObject {
    int data = 42;
    void access() {}
};

class SmartPointer {
private:
    ManagedObject* m_ptr;
public:
    SmartPointer(ManagedObject* p) : m_ptr(p) {}

    // Overloading -> must return a raw pointer
    // to the object whose members are accessed.
    ManagedObject* operator->() const {
        return m_ptr;
    }

    // Usage: SmartPointer sp(...);
    // sp->data;  // accesses m_ptr->data
    // sp->access();
};
